// 1. Parameter Validation
if (gb_input.rate_rad_s == NULL) {
    gb_output.mode = GB_OFF;
    gb_output.count = 0;
    gb_output.rejected_windows = 0;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s.x = 0.0; gb_output.bias_rad_s.y = 0.0; gb_output.bias_rad_s.z = 0.0;
    gb_output.variance_rad_s2.x = 0.0; gb_output.variance_rad_s2.y = 0.0; gb_output.variance_rad_s2.z = 0.0;
    return;
}
if (!isfinite(gb_config.stationary_limit_rad_s) || gb_config.stationary_limit_rad_s < 0.0 ||
    !isfinite(gb_config.max_sample_delta_rad_s) || gb_config.max_sample_delta_rad_s < 0.0 ||
    !isfinite(gb_config.max_stddev_rad_s) || gb_config.max_stddev_rad_s < 0.0 ||
    gb_config.required_samples < 3 || gb_config.required_samples > 100 ||
    gb_config.max_rejected_windows < 1 || gb_config.max_rejected_windows > 20 ||
    !isfinite(gb_config.drift_limit_rad_s) || gb_config.drift_limit_rad_s < 0.0 ||
    gb_config.drift_confirm_samples < 1 || gb_config.drift_confirm_samples > 20) {
    gb_output.mode = GB_FAULT;
    gb_output.count = 0;
    gb_output.rejected_windows = gb_state.rejected_windows;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s.x = 0.0; gb_output.bias_rad_s.y = 0.0; gb_output.bias_rad_s.z = 0.0;
    gb_output.variance_rad_s2.x = 0.0; gb_output.variance_rad_s2.y = 0.0; gb_output.variance_rad_s2.z = 0.0;
    return;
}

// 2. Disable Logic
if (!gb_input.enable) {
    gb_state.mode = GB_COLLECT;
    gb_state.count = 0;
    gb_state.rejected_windows = 0;
    gb_state.has_previous = 0;
    gb_state.mean_rad_s.x = 0.0; gb_state.mean_rad_s.y = 0.0; gb_state.mean_rad_s.z = 0.0;
    gb_state.m2_rad_s2.x = 0.0; gb_state.m2_rad_s2.y = 0.0; gb_state.m2_rad_s2.z = 0.0;
    gb_state.previous_rate_rad_s.x = 0.0; gb_state.previous_rate_rad_s.y = 0.0; gb_state.previous_rate_rad_s.z = 0.0;
    gb_state.bias_rad_s.x = 0.0; gb_state.bias_rad_s.y = 0.0; gb_state.bias_rad_s.z = 0.0;
    gb_state.variance_rad_s2.x = 0.0; gb_state.variance_rad_s2.y = 0.0; gb_state.variance_rad_s2.z = 0.0;
    gb_state.drift_count = 0;

    gb_output.mode = GB_COLLECT;
    gb_output.count = 0;
    gb_output.rejected_windows = 0;
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s.x = 0.0; gb_output.bias_rad_s.y = 0.0; gb_output.bias_rad_s.z = 0.0;
    gb_output.variance_rad_s2.x = 0.0; gb_output.variance_rad_s2.y = 0.0; gb_output.variance_rad_s2.z = 0.0;
    return;
}

// 3. Fault Latch Check
if (gb_state.mode != GB_FAULT && gb_state.rejected_windows >= gb_config.max_rejected_windows) {
    gb_state.mode = GB_FAULT;
}

// 4. Output Initialization based on Mode
gb_output.mode = gb_state.mode;
gb_output.count = gb_state.count;
gb_output.rejected_windows = gb_state.rejected_windows;

if (gb_state.mode == GB_FAULT) {
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s.x = 0.0; gb_output.bias_rad_s.y = 0.0; gb_output.bias_rad_s.z = 0.0;
    gb_output.variance_rad_s2.x = 0.0; gb_output.variance_rad_s2.y = 0.0; gb_output.variance_rad_s2.z = 0.0;
    return;
}

// 5. READY Mode Drift Handling
if (gb_state.mode == GB_READY) {
    adcs_vec3_t diff = adcs_vec3_sub(gb_input.rate_rad_s, &gb_state.bias_rad_s);
    double dist = adcs_vec3_norm(&diff);
    if (dist <= gb_config.drift_limit_rad_s) {
        gb_state.drift_count = 0;
    } else {
        gb_state.drift_count++;
        if (gb_state.drift_count >= gb_config.drift_confirm_samples) {
            gb_state.mode = GB_COLLECT;
            gb_state.count = 0;
            gb_state.has_previous = 0;
            gb_state.mean_rad_s.x = 0.0; gb_state.mean_rad_s.y = 0.0; gb_state.mean_rad_s.z = 0.0;
            gb_state.m2_rad_s2.x = 0.0; gb_state.m2_rad_s2.y = 0.0; gb_state.m2_rad_s2.z = 0.0;
            gb_output.mode = GB_COLLECT;
            gb_output.count = 0;
            gb_output.bias_rad_s.x = 0.0; gb_output.bias_rad_s.y = 0.0; gb_output.bias_rad_s.z = 0.0;
            gb_output.variance_rad_s2.x = 0.0; gb_output.variance_rad_s2.y = 0.0; gb_output.variance_rad_s2.z = 0.0;
            return;
        }
    }
    gb_output.rejection = GB_REJECT_NONE;
    gb_output.bias_rad_s = gb_state.bias_rad_s;
    gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
    return;
}

// 6. COLLECT Mode Sample Gating
gb_output.rejection = GB_REJECT_NONE;
double norm = adcs_vec3_norm(gb_input.rate_rad_s);
int reject = 0;

if (norm > gb_config.stationary_limit_rad_s) {
    reject = 1;
    gb_output.rejection = GB_REJECT_RATE;
} else if (gb_state.has_previous) {
    adcs_vec3_t delta = adcs_vec3_sub(gb_input.rate_rad_s, &gb_state.previous_rate_rad_s);
    if (adcs_vec3_norm(&delta) > gb_config.max_sample_delta_rad_s) {
        reject = 1;
        gb_output.rejection = GB_REJECT_STEP;
    }
}

if (reject) {
    gb_state.count = 0;
    gb_state.has_previous = 0;
    gb_state.mean_rad_s.x = 0.0; gb_state.mean_rad_s.y = 0.0; gb_state.mean_rad_s.z = 0.0;
    gb_state.m2_rad_s2.x = 0.0; gb_state.m2_rad_s2.y = 0.0; gb_state.m2_rad_s2.z = 0.0;
    gb_state.rejected_windows++;
    gb_output.count = 0;
    gb_output.bias_rad_s.x = 0.0; gb_output.bias_rad_s.y = 0.0; gb_output.bias_rad_s.z = 0.0;
    gb_output.variance_rad_s2.x = 0.0; gb_output.variance_rad_s2.y = 0.0; gb_output.variance_rad_s2.z = 0.0;
    return;
}

// 7. Welford's Algorithm Update
gb_state.has_previous = 1;
gb_state.previous_rate_rad_s = *gb_input.rate_rad_s;
gb_state.count++;
unint32 n = gb_state.count;
double n_d = (double)n;

for (int i = 0; i < 3; i++) {
    double x = (i == 0) ? gb_input.rate_rad_s->x : ((i == 1) ? gb_input.rate_rad_s->y : gb_input.rate_rad_s->z);
    double old_mean = (i == 0) ? gb_state.mean_rad_s.x : ((i == 1) ? gb_state.mean_rad_s.y : gb_state.mean_rad_s.z);
    double new_mean = old_mean + (x - old_mean) / n_d;
    double m2 = (i == 0) ? gb_state.m2_rad_s2.x : ((i == 1) ? gb_state.m2_rad_s2.y : gb_state.m2_rad_s2.z);
    m2 += (x - old_mean) * (x - new_mean);

    if (i == 0) {
        gb_state.mean_rad_s.x = new_mean;
        gb_state.m2_rad_s2.x = m2;
    } else if (i == 1) {
        gb_state.mean_rad_s.y = new_mean;
        gb_state.m2_rad_s2.y = m2;
    } else {
        gb_state.mean_rad_s.z = new_mean;
        gb_state.m2_rad_s2.z = m2;
    }
}

// 8. Variance Check and State Transition
gb_output.rejection = GB_REJECT_NONE;
gb_output.bias_rad_s.x = 0.0; gb_output.bias_rad_s.y = 0.0; gb_output.bias_rad_s.z = 0.0;
gb_output.variance_rad_s2.x = 0.0; gb_output.variance_rad_s2.y = 0.0; gb_output.variance_rad_s2.z = 0.0;

if (n == gb_config.required_samples) {
    int noisy = 0;
    for (int i = 0; i < 3; i++) {
        double variance = (i == 0) ? gb_state.m2_rad_s2.x : ((i == 1) ? gb_state.m2_rad_s2.y : gb_state.m2_rad_s2.z);
        // Population variance = M2 / N
        double pop_var = variance / n_d;
        if (pop_var > gb_config.max_stddev_rad_s * gb_config.max_stddev_rad_s) {
            noisy = 1;
            break;
        }
    }

    if (noisy) {
        gb_state.count = 0;
        gb_state.has_previous = 0;
        gb_state.mean_rad_s.x = 0.0; gb_state.mean_rad_s.y = 0.0; gb_state.mean_rad_s.z = 0.0;
        gb_state.m2_rad_s2.x = 0.0; gb_state.m2_rad_s2.y = 0.0; gb_state.m2_rad_s2.z = 0.0;
        gb_state.rejected_windows++;
        gb_output.rejection = GB_REJECT_VARIANCE;
        return;
    } else {
        gb_state.mode = GB_READY;
        gb_state.bias_rad_s = gb_state.mean_rad_s;
        // Store population variance: M2 / N
        gb_state.variance_rad_s2.x = gb_state.m2_rad_s2.x / n_d;
        gb_state.variance_rad_s2.y = gb_state.m2_rad_s2.y / n_d;
        gb_state.variance_rad_s2.z = gb_state.m2_rad_s2.z / n_d;

        gb_output.mode = GB_READY;
        gb_output.bias_rad_s = gb_state.bias_rad_s;
        gb_output.variance_rad_s2 = gb_state.variance_rad_s2;
        return;
    }
}

// Still collecting, publish current population variance
gb_output.bias_rad_s.x = 0.0; gb_output.bias_rad_s.y = 0.0; gb_output.bias_rad_s.z = 0.0;
gb_output.variance_rad_s2.x = gb_state.m2_rad_s2.x / n_d;
gb_output.variance_rad_s2.y = gb_state.m2_rad_s2.y / n_d;
gb_output.variance_rad_s2.z = gb_state.m2_rad_s2.z / n_d;

