if (!isfinite(gb_config.drift_limit_rad_s) || gb_config.drift_limit_rad_s < 0.0) valid_config = 0;
if (gb_config.drift_confirm_samples < 1 || gb_config.drift_confirm_samples > 20) valid_config = 0;

if (gb_input.enable != 0 && gb_input.enable != 1) {
    valid_config = 0;
}

if (!valid_config) {
    gb_state.mode = GB_FAULT;
    gb_state.count = 0;
    gb_state.rejected_windows = gb_config.max_rejected_windows; 
    gb_state.has_previous = 0;
    gb_state.mean_rad_s.x = 0.0; gb_state.mean_rad_s.y = 0.0; gb_state.mean_rad_s.z = 0.0;
