gb_rejection_t current_rejection = GB_REJECT_NONE;

if (!adcs_is_finite_vec3(gb_input.rate_rad_s)) {
    current_rejection = GB_REJECT_RATE;
} else {
    double norm = adcs_vec3_norm(gb_input.rate_rad_s);
    if (norm > gb_config.stationary_limit_rad_s) {
        current_rejection = GB_REJECT_RATE;
